WITH expected AS (SELECT value AS entry FROM jsonb_array_elements($entries$[{"id":59580,"before":{"id":59580,"cost":"","name":"Maneuvering Mines","type":"feat","uuid":"6931318011410594","level":6,"access":"","rarity":"COMMON","traits":[5194],"actions":null,"special":"","trigger":"","version":"1.0","frequency":"","meta_data":{"source":{"url":"https://2e.aonsrd.com/feats/2824-maneuvering-mines","book":"Tech Core","page":"43"}},"created_at":"2026-10-15T19:43:39.065003+00:00","operations":[],"description":"Your mines push or pull creatures away from them. You gain the following new mods.\n\n- **Big Bang (mine exocortex):** Your mines blow enemies away. Creatures that fail their saving throw against the mine are pushed 5 feet directly away from the mine (or pushed 10 feet directly away from the mine and knocked prone on a critical failure). This is forced movement.\n- **Black Hole (mine exocortex):** Your mines harness gravity-bending technology. Creatures that fail their saving throw against the mine are pulled 5 feet toward the mine (or pulled 10 feet toward the mine and slowed 1 on a critical failure). This is forced movement.","availability":"STANDARD","requirements":"","prerequisites":["mine exocortex"],"content_source_id":900},"operations":[{"id":"39ac8a40-bc4a-40d4-a8de-50e3b4a8f4a1","type":"injectText","data":{"type":"feat","id":59021,"text":"**Maneuvering Mines**\n\nYour mines push or pull creatures away from them. You gain the following new mods.\n\n- **Big Bang (mine exocortex):** Your mines blow enemies away. Creatures that fail their saving throw against the mine are pushed 5 feet directly away from the mine (or pushed 10 feet directly away from the mine and knocked prone on a critical failure). This is forced movement.\n- **Black Hole (mine exocortex):** Your mines harness gravity-bending technology. Creatures that fail their saving throw against the mine are pulled 5 feet toward the mine (or pulled 10 feet toward the mine and slowed 1 on a critical failure). This is forced movement."}}]},{"id":59691,"before":{"id":59691,"cost":"","name":"Healing Mines","type":"feat","uuid":"5512001651619018","level":2,"access":"","rarity":"COMMON","traits":[5194],"actions":null,"special":"If you have the [High-Tech Medic](link_feat_59328) feat, you can apply any of the mods granted by that feat to your [healing mines](link_feat_59691).","trigger":"","version":"1.0","frequency":"","meta_data":{"source":{"url":"https://2e.aonsrd.com/feats/2812-healing-mines","book":"Tech Core","page":"42"}},"created_at":"2026-10-15T19:47:02.799811+00:00","operations":[],"description":"You've designed a mine that explodes with healing medicine. You gain the following new mod.\n\n**Healing Mines (mine exocortex):** Your mine uses tiny four-sided syringes full of concentrated medicine. Instead of dealing damage, your healing mine causes creatures to regain a number of Hit Points equal to the mine's number of damage dice. Unlike your usual mines, creatures in the area don't attempt a saving throw. At 8th level, add your Intelligence modifier to the number of Hit Points regained.","availability":"STANDARD","requirements":"","prerequisites":["mine exocortex"],"content_source_id":900},"operations":[{"id":"e1b1f163-1d53-44ff-8f73-0bf5187e5c2a","type":"injectText","data":{"type":"feat","id":59021,"text":"**Healing Mines**\n\nYou've designed a mine that explodes with healing medicine. You gain the following new mod.\n\n**Healing Mines (mine exocortex):** Your mine uses tiny four-sided syringes full of concentrated medicine. Instead of dealing damage, your healing mine causes creatures to regain a number of Hit Points equal to the mine's number of damage dice. Unlike your usual mines, creatures in the area don't attempt a saving throw. At 8th level, add your Intelligence modifier to the number of Hit Points regained."}}]},{"id":59452,"before":{"id":59452,"created_at":"2026-10-15T17:58:36.860185+00:00","operations":[],"name":"Aerial Hologram","actions":null,"level":1,"rarity":"COMMON","prerequisites":[],"frequency":"","cost":"","trigger":"","requirements":"","access":"","description":"Your core can levitate, enabling your hardlight body to fly. You gain a fly Speed equal to your Speed. When you [Disable Hardlight Projector](link_feat_59157), your core hovers in place 3 feet above the ground, rather than falling to the ground.","special":"If you’re a [hover ad living hologram](link_heritage_59401), you instead gain a fly Speed equal to your Speed + 10 feet.","type":"feat","meta_data":{"source":{"url":"https://2e.aonsrd.com/feats/2701-aerial-hologram","book":"Tech Core","page":"11"}},"traits":[5198],"content_source_id":900,"version":"1.0","uuid":"12926163964722","availability":"STANDARD"},"operations":[{"id":"35dfda5e-ddc2-404c-b75e-8d4d7132f987","type":"conditional","data":{"conditions":[{"id":"9b6a36c0-137b-4f61-a5fe-c74bddee32c7","name":"HERITAGE_IDS","data":{"name":"HERITAGE_IDS","type":"list-str","value":[]},"type":"list-str","operator":"INCLUDES","value":"59401"}],"trueOperations":[{"id":"eef0bc14-6f13-40f2-9082-880bfc694f90","type":"bindValue","data":{"variable":"SPEED_FLY","value":{"storeId":"CHARACTER","variable":"SPEED","offset":10,"includeBonuses":true}}}],"falseOperations":[{"id":"aa03fade-f6d1-480a-9451-386b5de1b509","type":"bindValue","data":{"variable":"SPEED_FLY","value":{"storeId":"CHARACTER","variable":"SPEED","includeBonuses":true}}}]}}]},{"id":59681,"before":{"id":59681,"created_at":"2026-10-15T19:47:02.799811+00:00","operations":[],"name":"Aerobatics Mastery","actions":null,"level":7,"rarity":"COMMON","prerequisites":["Master in Acrobatics"],"frequency":"","cost":"","trigger":"","requirements":"","access":"","description":"You can gracefully perform aerial stunts as if flying were second nature. You gain a +2 circumstance bonus to Acrobatics checks to [Maneuver in Flight](link_action_19740) and can combine two maneuvers into a single action, such as reversing direction while making a steep descent or hovering in gale force winds. The DC of the Acrobatics check is equal to the DC of the most difficult maneuver + 5. If you’re legendary in Acrobatics, you can combine three such maneuvers into a single action; the DC of the Acrobatics check is equal to the DC of the most difficult maneuver + 10. Regardless of the combination, these maneuvers rarely allow you to move further than your fly Speed.","special":"","type":"feat","meta_data":{"source":{"url":"https://2e.aonsrd.com/feats/2669-aerobatics-mastery","book":"Tech Core","page":"81"}},"traits":[1437,1438],"content_source_id":900,"version":"1.0","uuid":"5096757730000536","availability":"STANDARD"},"operations":[{"id":"5966dd78-917e-4227-a29b-2e04d6b1bf4f","type":"injectText","data":{"type":"action","id":19740,"text":"**Aerobatics Mastery**\n\nYou can gracefully perform aerial stunts as if flying were second nature. You gain a +2 circumstance bonus to Acrobatics checks to [Maneuver in Flight](link_action_19740) and can combine two maneuvers into a single action, such as reversing direction while making a steep descent or hovering in gale force winds. The DC of the Acrobatics check is equal to the DC of the most difficult maneuver + 5. If you’re legendary in Acrobatics, you can combine three such maneuvers into a single action; the DC of the Acrobatics check is equal to the DC of the most difficult maneuver + 10. Regardless of the combination, these maneuvers rarely allow you to move further than your fly Speed."}},{"id":"a341f56f-5589-4d6c-906f-7756c2ea4006","type":"addBonusToValue","data":{"variable":"SKILL_ACROBATICS","value":2,"type":"circumstance","text":"to Maneuver in Flight"}}]},{"id":59595,"before":{"id":59595,"created_at":"2026-10-15T19:43:39.065003+00:00","operations":[],"name":"Expert Mechanic","actions":null,"level":12,"rarity":"COMMON","prerequisites":["Mechanic Dedication"],"frequency":"","cost":"","trigger":"","requirements":"","access":"","description":"You become an expert in mechanic class DC, and in Computers or Crafting. If you’re already an expert in those skills, you instead become an expert in another skill you’re trained in.","special":"","type":"feat","meta_data":{"source":{"url":"https://2e.aonsrd.com/feats/2929-expert-mechanic","book":"Tech Core","page":"62"}},"traits":[1439,5313],"content_source_id":900,"version":"1.0","uuid":"776965940842435","availability":"STANDARD"},"operations":[{"id":"961edcbb-f582-4aa5-b8a5-db06db286289","type":"adjValue","data":{"variable":"CLASS_DC","value":{"value":"E"}}},{"id":"192025eb-60c6-45db-b623-1b4d775c2900","type":"select","data":{"title":"Select a Skill to Become Expert","description":"Become an expert in Computers or Crafting. If both are already expert, become an expert in another skill you are trained in.","modeType":"PREDEFINED","optionType":"ADJ_VALUE","optionsPredefined":[{"id":"SKILL_COMPUTERS","type":"ADJ_VALUE","operation":{"id":"SKILL_COMPUTERS","type":"adjValue","data":{"variable":"SKILL_COMPUTERS","value":{"value":"E"}}}},{"id":"SKILL_CRAFTING","type":"ADJ_VALUE","operation":{"id":"SKILL_CRAFTING","type":"adjValue","data":{"variable":"SKILL_CRAFTING","value":{"value":"E"}}}}],"optionsFilters":{"id":"9a01a896-7aac-484b-826b-34e21752e07a","type":"ADJ_VALUE","group":"SKILL","value":{"value":"E"},"skillRules":"expert-mechanic"}}}]},{"id":58881,"before":{"id":58881,"created_at":"2026-10-08T18:10:28.569615+00:00","operations":[],"name":"Programmer","actions":null,"level":1,"rarity":"COMMON","prerequisites":["trained in Computers"],"frequency":"","cost":"","trigger":"","requirements":"","access":"","description":"You can write computer programs. You can [Earn Income](link_action_19631) using Computers, spending your time programming apps for clients. You can also [Craft](link_action_19617) items with the [virtual](link_trait_5237) trait. You can use [Programmer](link_feat_58881) to [Craft](link_action_19617) [tech](link_trait_4506) items that don’t have the [virtual](link_trait_5237) trait, but you can only cover up to a quarter of the item’s cost in raw materials; the remaining Crafting has to be completed by someone using the Crafting skill.","special":"","type":"feat","meta_data":{"skill":"Computers","source":{"url":"https://2e.aonsrd.com/feats/2696-programmer","book":"Tech Core","page":"85"}},"traits":[1437,1438],"content_source_id":900,"version":"1.0","uuid":"2568001111156477","availability":"STANDARD"},"operations":[{"id":"98f7abd2-303f-46ea-b3e5-9b2959ba289f","type":"injectText","data":{"type":"action","id":19631,"text":"**Programmer**\n\nYou can write computer programs. You can [Earn Income](link_action_19631) using Computers, spending your time programming apps for clients. You can also [Craft](link_action_19617) items with the [virtual](link_trait_5237) trait. You can use [Programmer](link_feat_58881) to [Craft](link_action_19617) [tech](link_trait_4506) items that don’t have the [virtual](link_trait_5237) trait, but you can only cover up to a quarter of the item’s cost in raw materials; the remaining Crafting has to be completed by someone using the Crafting skill."}},{"id":"516dabe1-b566-4850-a232-2152ad1ca95f","type":"injectText","data":{"type":"action","id":19617,"text":"**Programmer**\n\nYou can write computer programs. You can [Earn Income](link_action_19631) using Computers, spending your time programming apps for clients. You can also [Craft](link_action_19617) items with the [virtual](link_trait_5237) trait. You can use [Programmer](link_feat_58881) to [Craft](link_action_19617) [tech](link_trait_4506) items that don’t have the [virtual](link_trait_5237) trait, but you can only cover up to a quarter of the item’s cost in raw materials; the remaining Crafting has to be completed by someone using the Crafting skill."}}]},{"id":59248,"before":{"id":59248,"created_at":"2026-10-13T03:45:16.188634+00:00","operations":[],"name":"Auto Spellshape","actions":null,"level":20,"rarity":"COMMON","prerequisites":[],"frequency":"","cost":"","trigger":"","requirements":"","access":"","description":"You exploit magical shortcuts to effortlessly alter your spells. You can use [spellshape](link_trait_1465) single actions as free actions.","special":"","type":"feat","meta_data":{"source":{"url":"https://2e.aonsrd.com/feats/2920-auto-spellshape","book":"Tech Core","page":"61"}},"traits":[5195],"content_source_id":900,"version":null,"uuid":"74128761392926","availability":null},"operations":[{"id":"f56f6cd1-50fe-40c9-916e-4aa496f50321","type":"injectText","data":{"type":"trait","id":1465,"text":"**Auto Spellshape**\n\nYou exploit magical shortcuts to effortlessly alter your spells. You can use [spellshape](link_trait_1465) single actions as free actions."}}]},{"id":59685,"before":{"id":59685,"created_at":"2026-10-15T19:47:02.799811+00:00","operations":[],"name":"Magical Shorthand","actions":null,"level":2,"rarity":"COMMON","prerequisites":["Expert in Arcana, Expert in Nature, Expert in Occultism, or Expert in Religion"],"frequency":"","cost":"","trigger":"","requirements":"","access":"","description":"Learning spells comes easily to you. When you succeed at [Learning a Spell](link_action_19736), it takes 10 minutes regardless of the spell's rank. If you would succeed on the check, you critically succeed instead. If you fail, you can try again after a week or after you gain a level, whichever is first.\n\nYou can use downtime to learn and inscribe new spells. This works as if you were using [Earn Income](link_action_19631) with the tradition's associated skill, but instead of gaining money, you choose a spell available for you to learn and gain a discount on learning it, learning it for free if your earned income equals or exceeds its cost.","special":"","type":"feat","meta_data":{"source":{"url":"https://2e.aonsrd.com/feats/2688-magical-shorthand","book":"Tech Core","page":"84"}},"traits":[1437,1438],"content_source_id":900,"version":"1.0","uuid":"280229246841311","availability":"STANDARD"},"operations":[{"id":"903b383c-e3e3-4ceb-b7a2-0417fa409f1b","type":"injectText","data":{"type":"action","id":19736,"text":"**Magical Shorthand**\n\nLearning spells comes easily to you. When you succeed at [Learning a Spell](link_action_19736), it takes 10 minutes regardless of the spell's rank. If you would succeed on the check, you critically succeed instead. If you fail, you can try again after a week or after you gain a level, whichever is first.\n\nYou can use downtime to learn and inscribe new spells. This works as if you were using [Earn Income](link_action_19631) with the tradition's associated skill, but instead of gaining money, you choose a spell available for you to learn and gain a discount on learning it, learning it for free if your earned income equals or exceeds its cost."}}]}]$entries$::jsonb)), present AS (
 SELECT 1 FROM public.ability_block WHERE content_source_id=900 AND id IN (59580,59691,59452,59681,59595,58881,59248,59685)
)
SELECT 'mine-mod-rules' AS id, NOT EXISTS (SELECT 1 FROM present) OR (
 (SELECT count(*) FROM expected e JOIN public.ability_block a ON a.id=(e.entry->>'id')::bigint
 WHERE ((to_jsonb(a)-'updated_at'-'search_tsv'-'operations')||jsonb_build_object('uuid',a.uuid::text))=(e.entry->'before')-'operations'
 AND to_jsonb(a.operations)=e.entry->'operations')=8
 AND EXISTS (SELECT 1 FROM public.ability_block WHERE id=59021 AND content_source_id=900 AND name='Modify')
 AND NOT EXISTS (SELECT 1 FROM public.content_update WHERE ref_id IN (59580,59691,59452,59681,59595,58881,59248,59685) AND type='ability-block'
 AND (status->>'state' IS NULL OR status->>'state' NOT IN ('APPROVED','REJECTED')))
 ) AS passed;
